const client = new Docker({ socketPath: '/var/run/docker.sock' });
const tempArr = [];

client.pull('restic/restic', { "disable-content-trust": "false" }, function (err, pull) {
    if (err) {
        msg.payload = err.message;
        return node.send([msg, null]);
    }
    client.modem.followProgress(pull, (err, _output) => {
        if (err) {
            msg.payload = err.message;
            return node.send([msg, null]);
        }

        const eventEmmiter = client.run('restic/restic', msg.payload.command, false, msg.payload.options, {}, (err, _data, _container) => {
            if (err) {
                msg.payload = err.message;
                return node.send([msg, null]);
            }
        });

        if (eventEmmiter == null) {
            msg.payload = "eventEmmiter is null";
            return node.send([msg, null]);
        }

        eventEmmiter.on('stream', (stream) => {
            stream.on('data', data => {
                tempArr.push(data.toString());
            });
            stream.on('end', () => {
                msg.payload = tempArr;
                return node.send([null, msg]);
            })
        }).on('error', (err) => {
            msg.payload = err.message;
            return node.send([msg, null]);
        });
    });
});

