function isDiaUtil(data) {
    const diaDaSemana = data.getDay();
    return diaDaSemana > 0 && diaDaSemana < 6;
}

function verificarJanelaDeExecucao(dataAtual, diaInicio, diaFim) {
    const diaDoMes = dataAtual.getDate();

    if (diaDoMes < diaInicio || diaDoMes > diaFim) {
        return false;
    }

    if (!isDiaUtil(dataAtual)) {
        return false;
    }

    for (let diaAnterior = diaInicio; diaAnterior < diaDoMes; diaAnterior++) {
        const dataAnterior = new Date(dataAtual.getFullYear(), dataAtual.getMonth(), diaAnterior);
        if (isDiaUtil(dataAnterior)) {
            return false;
        }
    }

    return true;
}
